import { Currency } from './currency-model';
import { FormulaType } from './formula-type.enum';
import { ItemBlock } from './item-block.model';
import { SkillBlock } from './skill-block.model';
import { SpellBlock, CastingSpellEntry, ActiveSkillEntry } from './spell-block-model';
import { StatBlock } from './stat-block.model';
import { StatusBlock } from './status-block.model';
import { RuneBlock } from './rune-block.model';
import { ActiveStatusEffect } from './status-effect.model';
import { SoulBlock } from './soul-block.model';
import { CompanionBlock } from './companion-block.model';

export interface SheetTrashItem {
  type: 'item' | 'equipment' | 'rune' | 'spell' | 'skill';
  data: ItemBlock | RuneBlock | SpellBlock | SkillBlock;
  deletedAt: number; // Timestamp
}

export interface HerstellenEntry {
  id: string;   // Unique identifier (uuid-style)
  label: string; // What is being crafted, e.g. "Schwerter"
  rank: number;
}

export interface CharacterSheet {
  id?: string; // Optional because it's not stored in the JSON file itself
  runes: (RuneBlock | null)[];
  // Character
  name: string;
  race: string;
  raceId?: string; // Reference to the Race object in races.json
  selectedRacialSkills?: { [level: number]: string }; // Maps level to selected skill name for racial skill choices
  age: number;
  alignment: string;
  size: string;
  extrainfo: string;
  portrait?: string;
  worldName?: string; // The world this character belongs to
  /** User ids that fully control this character (creator auto-added; admin can reassign). */
  controllerUserIds?: string[];
  // Klassen
  primary_class: string;
  secondary_class: string;
  level: number;
  learned_classes: string;
  fokusMultiplier: number;
  fokusBonus: number;
  strength: StatBlock;
  dexterity: StatBlock;
  speed: StatBlock;
  intelligence: StatBlock;
  chill: StatBlock;
  constitution: StatBlock;
  skills: SkillBlock[];
  statuses: StatusBlock[];
  inventory: (ItemBlock | null)[];
  equipment: ItemBlock[];
  /** Physical crafting resources (raw materials, ingredients, extractors) — separate from inventory. */
  resources?: ItemBlock[];
  carryCapacityMultiplier: number;
  carryCapacityBonus: number;
  speedPenaltyNegation?: number; // Reduces speed penalties from armor/encumbrance
  spells: SpellBlock[];
  currency: Currency;
  trash: SheetTrashItem[]; // Recycle bin for deleted items
  activeStatusEffects: ActiveStatusEffect[]; // Status effects currently applied to this character
  seenStatusEffectIds: string[]; // IDs of status effects this character has encountered (allows re-application from sheet)
  // Fähigkeiten System (Skill Tree)
  talentPoints: number;           // Fähigkeitspunkte zum Ausgeben
  talentPointsBonus: number;      // GM-zugewiesene Bonus-Fähigkeitspunkte
  learnedSkillIds: string[];      // IDs of skills learned from the skill tree
  /** Skill-tree PLANNING: skills the player intends to take later. Never grants anything. */
  plannedSkillIds?: string[];
  /** Classes whose skills are all learned AND the player ticked "Veredelung abgeschlossen". */
  masteredClassesConfirmed?: string[];
  /** Classes a GM force-unlocked, bypassing the tree's progression rules. */
  gmUnlockedClasses?: string[];
  // Talente System (DnD-style stat proficiencies)
  talentRanks?: { [talentId: string]: number }; // Invested ranks per talent
  talentRankBonus?: number;       // GM-assigned bonus talent points for the talent system
  herstellenEntries?: HerstellenEntry[]; // Custom crafting talents (multiple, each with own name)
  // Free Stat Points System
  freeStatPoints: number;         // Available free stat points to spend
  freeStatPointsBonus: number;    // GM-assigned bonus stat points
  // Derived stat bonuses
  grundbonusBonus?: number;       // Extra added to Grundbonus (⌊Level/5⌋ + ⌊Wille/5⌋)
  reaktionswertBonus?: number;    // Extra added to Reaktion (10 − ⌊Wille/5⌋ − ⌊Level/5⌋)
  // Backstory
  backstory?: string;             // Character background story (supports simple markdown)
  // Active / Sustained Skills & Spells
  activeSkillNames?: string[];    // Names of currently toggled-on perRound skills (spellcast-window toggle)
  activeSkillEntries?: ActiveSkillEntry[]; // Active skill instances (supports multiple; bottom-panel activation)
  castingSpells?: CastingSpellEntry[]; // Spells actively being cast (cast-level tracking)
  spellCastBonus?: number;        // Saved bonus added to every d20 cast roll
  // Material / Brewing Knowledge System
  knownMaterialIds?: string[];     // IDs of materials the player has knowledge of
  knownForgeTraitIds?: string[];   // IDs of forge traits the player has knowledge of
  knownIngredientIds?: string[];   // IDs of brew ingredients (Wirkstoffe)
  knownExtractorIds?: string[];    // IDs of extractors
  knownBrewTraitIds?: string[];    // IDs of brew traits (Braumerkmale)
  // Souls captured from beings (Wissen → Seelen), usable as Begleiter material
  souls?: SoulBlock[];
  // Begleiter: summons/familiars the character keeps ready (Begleiter tab); summoning runes point here
  companions?: CompanionBlock[];
}

export function createEmptySheet(): CharacterSheet {
  return {
    name: '',
    race: '',
    age: 0,
    alignment: '',
    size: '',
    extrainfo: '',
    primary_class: '',
    secondary_class: '',
    level: 1,
    learned_classes: '',
    strength: createEmptyStatBlock('Stärke'),
    dexterity: createEmptyStatBlock('Geschicklichkeit'),
    speed: createEmptyStatBlock('Geschwindigkeit'),
    intelligence: createEmptyStatBlock('Intelligenz'),
    chill: createEmptyStatBlock('Wille'),
    constitution: createEmptyStatBlock('Konstitution'),
    skills: [],
    inventory: [],
    equipment: [],
    resources: [],
    carryCapacityMultiplier: 1,
    carryCapacityBonus: 0,
    speedPenaltyNegation: 0,
    statuses: createBasicStatuses(),
    runes: [],
    spells: [],
    fokusMultiplier: 1,
    fokusBonus: 0,
    currency: {
      copper: 0,
      silver: 0,
      gold: 0,
      platinum: 0,
    },
    trash: [],
    activeStatusEffects: [],
    seenStatusEffectIds: [],
    talentPoints: 2,
    talentPointsBonus: 0,
    learnedSkillIds: [],
    talentRanks: {},
    talentRankBonus: 0,
    herstellenEntries: [],
    freeStatPoints: 0,
    freeStatPointsBonus: 0,
    grundbonusBonus: 0,
    reaktionswertBonus: 0,
    backstory: '',
    knownMaterialIds: [],
    knownForgeTraitIds: [],
    knownIngredientIds: [],
    knownExtractorIds: [],
    knownBrewTraitIds: [],
  };
}

function createEmptyStatBlock(name: string): StatBlock {
  return new StatBlock(name, 10, 5, 0);
}

